Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
drm/amdgpu: Fix memory leak in amdgpu_ras_init()

When amdgpu_nbio_ras_sw_init() fails in amdgpu_ras_init(), the function
returns directly without freeing the allocated con structure, leading
to a memory leak.

Fix this by jumping to the release_con label to properly clean up the
allocated memory before returning the error code.

Compile tested only. Issue found using a prototype static analysis tool
and code review.

Fixes: fdc94d3a8c88 ("drm/amdgpu: Rework pcie_bif ras sw_init")
Reviewed-by: Tao Zhou <tao.zhou1@amd.com>
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>

Here is the root cause:
In `amdgpu_ras_init()`, when `amdgpu_nbio_ras_sw_init()` fails, the function returns immediately without freeing the previously allocated `con` structure, leading to a memory leak.

Here is the patch:

 int amdgpu_ras_init(struct amdgpu_device *adev)
 {
 	struct amdgpu_ras *con = amdgpu_ras_get_context(adev);
 	int r;

 	if (con)
 		return 0;

 	con = kzalloc(sizeof(*con) +
 			sizeof(struct ras_manager) * AMDGPU_RAS_BLOCK_COUNT +
 			sizeof(struct ras_manager) * AMDGPU_RAS_MCA_BLOCK_COUNT,
 			GFP_KERNEL);
 	if (!con)
 		return -ENOMEM;

 	con->adev = adev;
 	INIT_DELAYED_WORK(&con->ras_counte_delay_work, amdgpu_ras_counte_dw);
 	atomic_set(&con->ras_ce_count, 0);
 	atomic_set(&con->ras_ue_count, 0);

 	con->objs = (struct ras_manager *)(con + 1);

 	amdgpu_ras_set_context(adev, con);

 	amdgpu_ras_check_supported(adev);

 	if (!adev->ras_enabled || adev->asic_type == CHIP_VEGA10) {
 		/* set gfx block ras context feature for VEGA20 Gaming
 		 * send ras disable cmd to ras ta during ras late init.
 		 */
 		if (!adev->ras_enabled && adev->asic_type == CHIP_VEGA20) {
 			con->features |= BIT(AMDGPU_RAS_BLOCK__GFX);

 			return 0;
 		}

 		r = 0;
 		goto release_con;
 	}

 	con->update_channel_flag = false;
 	con->features = 0;
 	con->schema = 0;
 	INIT_LIST_HEAD(&con->head);
 	/* Might need get this flag from vbios. */
 	con->flags = RAS_DEFAULT_FLAGS;

 	/* initialize nbio ras function ahead of any other
 	 * ras functions so hardware fatal error interrupt
 	 * can be enabled as early as possible */
 	switch (amdgpu_ip_version(adev, NBIO_HWIP, 0)) {
 	case IP_VERSION(7, 4, 0):
 	case IP_VERSION(7, 4, 1):
 	case IP_VERSION(7, 4, 4):
 		if (!adev->gmc.xgmi.connected_to_cpu)
 			adev->nbio.ras = &nbio_v7_4_ras;
 		break;
 	case IP_VERSION(4, 3, 0):
 		if (adev->ras_hw_enabled & (1 << AMDGPU_RAS_BLOCK__DF))
 			/* unlike other generation of nbio ras,
 			 * nbio v4_3 only support fatal error interrupt
 			 * to inform software that DF is freezed due to
 			 * system fatal error event. driver should not
 			 * enable nbio ras in such case. Instead,
 			 * check DF RAS */
 			adev->nbio.ras = &nbio_v4_3_ras;
 		break;
 	case IP_VERSION(6, 3, 1):
 		if (adev->ras_hw_enabled & (1 << AMDGPU_RAS_BLOCK__DF))
 			/* unlike other generation of nbio ras,
 			 * nbif v6_3_1 only support fatal error interrupt
 			 * to inform software that DF is freezed due to
 			 * system fatal error event. driver should not
 			 * enable nbio ras in such case. Instead,
 			 * check DF RAS
 			 */
 			adev->nbio.ras = &nbif_v6_3_1_ras;
 		break;
 	case IP_VERSION(7, 9, 0):
 	case IP_VERSION(7, 9, 1):
 		if (!adev->gmc.is_app_apu)
 			adev->nbio.ras = &nbio_v7_9_ras;
 		break;
 	default:
 		/* nbio ras is not available */
 		break;
 	}

 	/* nbio ras block needs to be enabled ahead of other ras blocks
 	 * to handle fatal error */
 	r = amdgpu_nbio_ras_sw_init(adev);
 	if (r)
-		return r;
+		goto release_con;

 	if (adev->nbio.ras &&
 	    adev->nbio.ras->init_ras_controller_interrupt) {
 		r = adev->nbio.ras->init_ras_controller_interrupt(adev);
 		if (r)
 			goto release_con;
 	}

 	if (adev->nbio.ras &&
 	    adev->nbio.ras->init_ras_err_event_athub_interrupt) {
 		r = adev->nbio.ras->init_ras_err_event_athub_interrupt(adev);
 		if (r)
 			goto release_con;
 	}

 	/* Packed socket_id to ras feature mask bits[31:29] */
 	if (adev->smuio.funcs &&
 	    adev->smuio.funcs->get_socket_id)
 		con->features |= ((adev->smuio.funcs->get_socket_id(adev)) <<
 					AMDGPU_RAS_FEATURES_SOCKETID_SHIFT);

 	/* Get RAS schema for particular SOC */
 	con->schema = amdgpu_get_ras_schema(adev);

 	amdgpu_ras_init_reserved_vram_size(adev);

 	if (amdgpu_ras_fs_init(adev)) {
 		r = -EINVAL;
 		goto release_con;
 	}

 	if (amdgpu_ras_aca_is_supported(adev)) {
 		if (amdgpu_aca_is_enabled(adev))
 			r = amdgpu_aca_init(adev);
 		else
 			r = amdgpu_mca_init(adev);
 		if (r)
 			goto release_con;
 	}

 	con->init_task_pid = task_pid_nr(current);
 	get_task_comm(con->init_task_comm, current);

 	mutex_init(&con->critical_region_lock);
 	INIT_LIST_HEAD(&con->critical_region_head);

 	dev_info(adev->dev, "RAS INFO: ras initialized successfully, "
 		 "hardware ability[%x] ras_mask[%x]\n",
 		 adev->ras_hw_enabled, adev->ras_enabled);

 	return 0;
 release_con:
 	amdgpu_ras_set_context(adev, NULL);
 	kfree(con);

 	return r;
 }



